#include "stdlib/ml/base/loss/float32/huber_gradient.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/signumf.h"
#include "stdlib/constants/float32/nan.h"

/**
* Computes the Huber loss gradient with respect to a model parameter for a single-precision floating-point number.
*
* @param x    input value
* @param d    threshold
* @param y    true target value
* @param p    predicted value
* @return     Huber loss gradient
*
* @example
* float out = stdlib_base_float32_huber_gradient( 2.5f, 2.0f, 8.0f, 0.202f );
* // returns -5.0f
*/
float stdlib_base_float32_huber_gradient( const float x, const float d, const float y, const float p ) {
	float z;
	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_nanf( d ) || stdlib_base_is_nanf( y ) || stdlib_base_is_nanf( p ) ) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	z = y - p;
	if ( stdlib_base_absf( z ) <= d ) {
		return -z * x;
	}
	return -d * stdlib_base_signumf( z ) * x;
}
